CREATE TABLE IF NOT EXISTS admin_users (id UUID PRIMARY KEY, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'super_admin', status TEXT NOT NULL DEFAULT 'active', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS admin_sessions (id UUID PRIMARY KEY, admin_user_id UUID NOT NULL REFERENCES admin_users(id), device_label TEXT NOT NULL, ip_hash TEXT NOT NULL, last_active_at TIMESTAMPTZ NOT NULL DEFAULT now(), revoked_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS admin_login_logs (id BIGSERIAL PRIMARY KEY, email_hash TEXT NOT NULL, result TEXT NOT NULL, request_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS captcha_challenges (id TEXT PRIMARY KEY, purpose TEXT NOT NULL, session_hash TEXT NOT NULL, target_hash TEXT NOT NULL DEFAULT '', expires_at TIMESTAMPTZ NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS captcha_tickets (id TEXT PRIMARY KEY, purpose TEXT NOT NULL, session_hash TEXT NOT NULL, target_hash TEXT NOT NULL DEFAULT '', expires_at TIMESTAMPTZ NOT NULL, consumed_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS app_configs (config_key TEXT PRIMARY KEY, config_value TEXT NOT NULL, is_secret BOOLEAN NOT NULL DEFAULT false, updated_by UUID, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_events (id UUID PRIMARY KEY, aggregate_type TEXT NOT NULL, aggregate_id TEXT NOT NULL, event_type TEXT NOT NULL, payload JSONB NOT NULL, occurred_at TIMESTAMPTZ NOT NULL DEFAULT now(), published_at TIMESTAMPTZ);
